# Test 1: Basic dataclass with @strict decorator
def test_basic_strict_dataclass():
    @strict
    @dataclass
    class Person:
        name: str
        age: int

    # Normal case
    p = Person(name="Alice", age=30)
    assert p.name == "Alice"
    assert p.age == 30

