# Test 2: @strict with accept_kwargs=True
def test_strict_with_accept_kwargs():
    @strict(accept_kwargs=True)
    @dataclass
    class Config:
        host: str = "localhost"
        port: int = 8080

    # Normal case with keyword arguments
    c = Config(host="example.com", port=9000)
    assert c.host == "example.com"
    assert c.port == 9000

    # Additional kwargs should be stored
